export interface StoredObject {
  stream: ReadableStream<Uint8Array>;
  /** Size in bytes when the backend reports it. */
  size?: number;
}

/** Where file bytes live. The `file` table maps a file id to the storage key. */
export interface StorageAdapter {
  put(key: string, body: Buffer, options: { contentType: string }): Promise<void>;
  /** Returns null when the key does not exist. */
  get(key: string): Promise<StoredObject | null>;
  /** Deleting a missing key is not an error. */
  delete(key: string): Promise<void>;
}

/** Keys are generated by us (`uploads/{uuid}/{name}`); anything that could escape the store is refused. */
export function assertSafeKey(key: string): void {
  const segments = key.split("/");
  if (
    key.length === 0 ||
    key.length > 300 ||
    key.startsWith("/") ||
    key.includes("\\") ||
    key.includes("\0") ||
    segments.some((s) => s === "" || s === "." || s === "..")
  ) {
    throw new Error(`Invalid storage key: ${JSON.stringify(key)}`);
  }
}
